// Chapter 3 art-registration guard. No images are generated by this check.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..');
const read=name=>JSON.parse(fs.readFileSync(path.join(root,name),'utf8'));
const a=read('story/artwork.draft.json');
const ch=read('story/chapters/chapter-03.reboot-candidate.json');
const m=read('story/storyboard-manifest.json');
const n=ch.nodes;
const scenes=new Set(Object.values(n).map(x=>x.scene));
const contexts=new Set(Object.values(n).filter(x=>x.speaker).map(x=>x.speaker+':'+x.scene));
const poses=new Set(Object.values(n).filter(x=>x.speaker).map(x=>x.speaker+':'+x.pose));
const archiveNote=/^ARCHIVED \/ RETIRED \/ UNUSED\b/;
const statuses=new Set(a.statusValues);
assert.match(a.direction,/CHAPTER 3 REBOOT — OWNER-APPROVED HUMAN STAGING EXCEPTION/,'new chapter-specific human art direction resolves older room rule');
function lifecycle(r,id){
  assert.ok(statuses.has(r.status),id+' legal art status');
  // Approved art gets exactly its proposed production path at gameplay integration (docs/105 step 2).
  if(r.status!=='integrated')assert.ok(r.assetPath===null||(r.status==='approved'&&r.assetPath===r.suggestedFilename),id+' no invented gameplay path');
}
assert.deepEqual([m.chapters.find(c=>c.id==='chapter-03').status,m.chapters.find(c=>c.id==='chapter-03').file],['draft','chapters/chapter-03.reboot-candidate.json'],'Chapter 3 activates only as the approved reboot (gameplay integration)');
assert.equal(scenes.size,14);
assert.equal(contexts.size,9);
assert.equal(poses.size,7);
assert.ok([...scenes].every(x=>x.startsWith('pavilion_reboot/')),'no obsolete Pavilion scene in candidate');
assert.equal(Object.keys(a.scenes).filter(x=>x.startsWith('pavilion_reboot/')).length,14);
let backgrounds=0,portraits=0;
for(const id of scenes){
  const scene=a.scenes[id];
  assert.ok(scene,id+' registered');
  assert.equal(scene.dimensions,'314x206',id);
  assert.equal(scene.kind,'scene',id);
  lifecycle(scene,id);
  assert.ok(scene.prompt.length>300,id+' specific prompt');
  assert.ok(!archiveNote.test(scene.notes),id+' not retired');
}
for(const pair of contexts){
  const [speaker,scene]=pair.split(':');
  assert.ok(speaker==='pavilion_attendant'||speaker==='pavilion_presenter',pair+' known human');
  const bg=a.scenes[scene]?.portraitBackground;
  assert.ok(bg,pair+' has matching independently authored backdrop brief');
  assert.equal(bg.dimensions,'564x278');
  lifecycle(bg,pair+' background');
}
for(const id of scenes){
  const bg=a.scenes[id].portraitBackground;
  if(bg)backgrounds++;
}
assert.equal(backgrounds,8,'exactly eight close POV backgrounds for nine contexts');
for(const id of poses){
  const fg=a.portraits[id];
  assert.ok(fg,'missing portrait '+id);
  assert.equal(fg.dimensions,'564x278');
  assert.equal(fg.foregroundFormat,'transparent-rgba-png');
  lifecycle(fg,id);
  assert.ok(a.scenes[fg.portraitBackgroundScene].portraitBackground);
  portraits++;
}
assert.equal(portraits,7);
let retired=0;
function oldRecord(r,id){
  assert.equal(r.status,'not-started',id+' unexpected old production status');
  assert.match(r.notes,archiveNote,id+' must be visibly quarantined');
  retired++;
}
for(const [id,r] of Object.entries(a.scenes))if(id.startsWith('pavilion/'))oldRecord(r,id);
for(const [id,r] of Object.entries(a.focus))if(id.startsWith('pavilion/'))oldRecord(r,id);
for(const [id,r] of Object.entries(a.deathScreens))if(id.startsWith('pavilion/'))oldRecord(r,id);
for(const id of ['registrar:idle','original_witness:screened'])oldRecord(a.portraits[id],id);
for(const [id,v] of Object.entries(a.items))if(id.startsWith('pavilion_')){
  for(const [variant,r] of Object.entries(v))oldRecord(r,id+':'+variant);
}
assert.equal(retired,65,'all legacy scene, focus, fatal, portrait, item art is quarantined');
assert.equal(Object.keys(a.deathScreens).filter(id=>id.startsWith('pavilion_reboot/')).length,0,'no CH3 death art');
assert.equal(Object.keys(a.items).filter(id=>id.startsWith('pavilion_reboot_')).length,0,'no new item art');
assert.equal(Object.keys(a.focus).filter(id=>id.startsWith('pavilion_reboot/')).length,0,'no Focus A art');
console.log('PASS CH3 artwork briefs: 14 scenes, 8 paired backgrounds, 7 foregrounds, 9 contexts; 65 historical calls archived; 0 death, new item or Focus A calls.');
